write: {"content": "import csv

def main():
    ru = 0
    foreign = 0
    with open('компоненты.csv', 'r', encoding='utf-8') as f:
        reader = csv.reader(f, delimiter=';')
        next(reader, None)  # заголовок
        for row in reader:
            if len(row) < 3:
                continue
            country = row[2].strip()
            if country == 'Россия':
                ru += 1
            else:
                foreign += 1
    total = ru + foreign
    pct = round((foreign / total) * 100) if total else 0
    print(f'Россия — {ru}')
    print(f'Иностранные — {foreign}')
    print(f'Доля иностранных — {pct}%')

if __name__ == '__main__':
    main()
